"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["31223"],{28231(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.avaliacao_sem_etapa","status":422,"titulo":"Fase que agrupa etapas sem nenhuma etapa que aconte\xe7a nela"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.avaliacao_sem_etapa","requisitos":[],"oQueAconteceu":["O cronograma do processo inclui uma fase que, pelo cadastro de fases, agrupa etapas\\npontuadas (como a das provas), mas nenhuma etapa do processo declara acontecer nela.\\nA fase existiria no edital sem nada para avaliar. A recusa sai com **422**.","A grava\xe7\xe3o do cronograma n\xe3o barra esse estado de imediato: ele \xe9 leg\xedtimo enquanto o\\ncertame est\xe1 sendo montado, e quem o recusa \xe9 a publica\xe7\xe3o. A mesma confer\xeancia vale\\nna retifica\xe7\xe3o em ato \xfanico, que gera nova\\nvers\xe3o, e a opera\xe7\xe3o \xe9 recusada antes de qualquer grava\xe7\xe3o."],"comoResolver":["Escolha o que reflete o edital:","- se o certame tem avalia\xe7\xe3o nessa fase, defina as etapas do processo\\n  (`PUT /api/selecao/processos-seletivos/{id}/etapas`) declarando a fase em que cada\\n  uma acontece;\\n- se o certame n\xe3o tem essa avalia\xe7\xe3o (por exemplo, classifica\xe7\xe3o importada), retire a\\n  fase do cronograma (`PUT /api/selecao/processos-seletivos/{id}/cronograma-fases`).","Repita a publica\xe7\xe3o ou a retifica\xe7\xe3o depois do ajuste."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);